"""Calculate monthly cleaning-service pay from the supplied CSV files."""

import csv
import json
import re
from collections import defaultdict
from datetime import date, timedelta
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path


DATASET = Path("/app/dataset")


def _read_csv(filename: str) -> list[dict[str, str]]:
    with (DATASET / filename).open(encoding="utf-8-sig", newline="") as file:
        return list(csv.DictReader(file))


def _billing_month(day: date, weekday: int) -> tuple[int, int]:
    """Assign dates before this month's first payday to the prior month."""
    first = day.replace(day=1)
    start = first + timedelta(days=(weekday - first.weekday()) % 7)
    if day < start:
        day = first - timedelta(days=1)
    return day.year, day.month


def answer() -> dict[str, list[int]]:
    employees = {
        row["PESEL"].strip(): Decimal(row["hourly_rate"])
        for row in _read_csv("employees.csv")
    }
    task_rates = {
        int(row["task_id"]): Decimal(row["pay_per_completion"])
        for row in _read_csv("tasks.csv")
    }

    records = []
    seen = set()
    for row in _read_csv("timesheet.csv"):
        pesel = row["employee_id"].strip()
        if pesel not in employees:
            # These IDs have overlapping shifts with registered employees;
            # treating them as spelling corrections would double-count work.
            continue
        try:
            day = date.fromisoformat(row["date"].strip())
        except ValueError:
            # April 31 and June 31 cannot be reliably assigned another date.
            continue

        hours = Decimal(row["hours_worked"])
        if not hours.is_finite() or hours < 0 or hours > 24:
            continue

        # Some lists lack an opening or closing bracket. Their comma-separated
        # integer IDs are intact and can be recovered without guessing IDs.
        task_text = row["performed_tasks"].strip().strip("[]").strip()
        if task_text:
            if not re.fullmatch(r"\d+(?:\s*,\s*\d+)*", task_text):
                continue
            tasks = tuple(int(value.strip()) for value in task_text.split(","))
        else:
            tasks = ()

        # IDs were reassigned to duplicated rows, so the ID is not a reliable
        # duplicate key. Normalize the task list before comparing records.
        key = (
            pesel, day, hours, tasks, row["facility_id"].strip(),
            Decimal(row["salary_amount"]), Decimal(row["bonus"]),
        )
        if key in seen:
            continue
        seen.add(key)

        # The task catalog supplies the authoritative bonus amounts. Unknown
        # tasks are excluded; valid hours and known tasks on that row remain.
        bonus = sum((task_rates.get(task, Decimal(0)) for task in tasks), Decimal(0))
        records.append((pesel, day, hours, bonus))

    if not records:
        return {pesel: [] for pesel in employees}

    payday_weekday = min(day for _, day, _, _ in records).weekday()
    totals = defaultdict(lambda: Decimal(0))
    months = set()
    for pesel, day, hours, bonus in records:
        month = _billing_month(day, payday_weekday)
        months.add(month)
        totals[pesel, month] += hours * employees[pesel] + bonus

    ordered_months = sorted(months)
    return {
        pesel: [
            int(totals[pesel, month].quantize(Decimal("1"), rounding=ROUND_HALF_UP))
            for month in ordered_months
        ]
        for pesel in employees
    }


if __name__ == "__main__":
    with open("/app/answer.json", "w", encoding="utf-8") as file:
        json.dump(answer(), file, indent=2)
        file.write("\n")
